SELECT MONTH(shipped_date) AS shipped_month, COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) AS returned_count, COUNT(DISTINCT cost) AS unique_statuss, ROUND((100 * SUM(CASE WHEN status = 'DELIVERED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_delivered FROM shipments GROUP BY MONTH(shipped_date) HAVING COUNT(CASE WHEN status = 'RETURNED' THEN 1 END) < 5 ORDER BY returned_count, shipped_month LIMIT 5
